<?php require __DIR__.'/layouts/admin_start.php'; ?>
<section class="module-panel"><h2>Liste des réservations</h2><form method="GET" style="margin-bottom:18px"><label for="status">Statut</label><select name="status" id="status"><option value="">Tous les statuts</option><?php foreach(Reservation::LABELS as $key=>$label): ?><option value="<?= $key ?>" <?= $status===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select> <button class="header-btn primary-btn">Filtrer</button></form>
<table><thead><tr><th>Référence / client</th><th>Médicament</th><th>Téléphone</th><th>Expiration</th><th>Statut</th><th>Actions</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="6">Aucune réservation.</td></tr><?php endif; ?><?php foreach($rows as $r): ?><tr><td><strong><?= htmlspecialchars($r['reference']) ?></strong><br><?= htmlspecialchars($r['client_name']) ?></td><td><?= htmlspecialchars($r['medicament_name']) ?> × <?= (int)$r['quantity'] ?></td><td><?= htmlspecialchars($r['phone']) ?></td><td><?= GuardPharmacy::date((int)$r['expires_at']) ?></td><td><?= htmlspecialchars(Reservation::LABELS[$r['status']]??$r['status']) ?></td><td><?php $actions=match($r['status']){'pending'=>['confirmed'=>'Confirmer','rejected'=>'Refuser'],'confirmed'=>['collected'=>'Marquer retirée','cancelled'=>'Annuler'],default=>[]};foreach($actions as $target=>$label): ?><form method="POST" style="display:inline"><?= csrfField() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn <?= in_array($target,['rejected','cancelled'])?'btn-danger':'btn-warning' ?>" name="target" value="<?= $target ?>"><?= $label ?></button></form><?php endforeach; ?></td></tr><?php endforeach; ?></tbody></table>
<div class="module-pagination"><?php if($page>1): ?><a href="?<?= htmlspecialchars(http_build_query(['status'=>$status,'page'=>$page-1])) ?>">Précédent</a><?php endif; ?><?php if($more): ?><a href="?<?= htmlspecialchars(http_build_query(['status'=>$status,'page'=>$page+1])) ?>">Suivant</a><?php endif; ?></div></section>
<?php require __DIR__.'/layouts/admin_end.php'; ?>
